/// Perfected Strike (Common, 2 energy). 6 base + 2 per "Strike" card in
/// deck. Conservative-port: deck-scan in handler is feasible but the
/// "Strike" name match is fragile — we apply the deck-scan as a best-effort
/// parity approximation.
/// `CalculatedDamage`: base + ExtraDamage for every Strike-tagged card you own.
/// Shared with the card face — see `crate::cards::preview`.
pub(crate) fn preview_perfected_strike(
    state: &CombatState,
    card: &Card,
    _target: Option<CreatureUid>,
) -> i32 {
    // C# `PerfectedStrike.cs`: damage multiplier =
    // `Owner.PlayerCombatState.AllCards.Count(c => c.Tags.Contains(Strike))`
    // where `AllCards = AllPiles.SelectMany(p => p.Cards)` over the FIVE
    // live piles (Hand, Draw, Discard, Exhaust, Play) — see
    // `PlayerCombatState.cs:42-54`. Bead `sts2-rs-jjref`: the prior port
    // scanned the raw `state.cards` instance arena by NAME substring, which
    // (a) counts ORPHANED instances no longer in any pile — e.g. a leaked
    // SeekerStrike copy (bead sts2-rs-fwe1x) — that C#'s pile-only
    // `AllCards` never sees, and (b) matched by `"STRIKE"`-in-name rather
    // than the canonical `CardTag::Strike` (over-counting e.g. MINION_STRIKE,
    // which is not Strike-tagged). Count Strike-TAGGED cards across the five
    // live piles, mirroring C# exactly. Each card lives in exactly one pile,
    // so the chained scan has no double-count. (Fuzz seeds 2293/3862:
    // PerfectedStrike over-counted by one orphaned SeekerStrike, dealing
    // +ExtraDamage too much.)
    let strike_count: i32 = state
        .player
        .hand
        .iter()
        .chain(state.player.draw.iter())
        .chain(state.player.discard.iter())
        .chain(state.player.exhaust.iter())
        .chain(state.player.play.iter())
        .filter(|uid| {
            let idx = uid.0.get() as usize - 1;
            state.cards[idx].has_tag(sts2_core::cards::CardTag::Strike)
        })
        .count()
        .try_into()
        .unwrap_or(0);
    // Bead `sts2-rs-4uybi`: C# `PerfectedStrike.cs` `ExtraDamageVar(2)`
    // with `OnUpgrade UpgradeValueBy(1m)` → +2 per Strike base / +3 upgraded.
    let per_strike = if card.upgraded { 3 } else { 2 };
    card.base_damage + per_strike * strike_count
}

pub(crate) fn play_perfected_strike(
    state: &mut CombatState,
    target: Option<CreatureUid>,
) -> EffectResult {
    let t = target.expect("PerfectedStrike: Enemy-targeted");
    let dmg = resolving_preview(state, preview_perfected_strike, target);
    let _ = deal_damage_player_to_enemy(state, t, dmg);
    EffectResult::Resolved
}

